// Cloudflare Worker for mainstgrowth.com: serves an X/OG link card that mirrors the
// Uniswap token page it forwards to. Humans are redirected client-side; crawlers get a 200 with tags.
const CHAIN = "ROBINHOOD";
const CHAIN_LABEL = "Robinhood Chain";
const TOKEN = "0x6b1d42927b1a84ec28fa88d4fc6fa7af404966be";
const DEST = "https://app.uniswap.org/explore/tokens/robinhood/" + TOKEN;
const SITE = "https://mainstgrowth.com";
const OG_PNG_B64 = "";

async function tokenInfo() {
  try {
    const res = await fetch("https://interface.gateway.uniswap.org/v1/graphql", {
      method: "POST",
      headers: { "content-type": "application/json", origin: "https://app.uniswap.org" },
      body: JSON.stringify({ query: `{ token(chain: ${CHAIN}, address: "${TOKEN}") { name symbol market { price { value } } } }` }),
      cf: { cacheTtl: 300, cacheEverything: true },
    });
    const t = (await res.json())?.data?.token;
    if (t?.symbol) return { name: t.name || t.symbol, symbol: t.symbol, price: t.market?.price?.value ?? null };
  } catch {}
  return { name: "PAIR", symbol: "PAIR", price: null };
}

function fmtPrice(p) {
  if (p == null) return "";
  const digits = p >= 1 ? 2 : Math.min(8, Math.max(2, 2 - Math.floor(Math.log10(p))));
  return " Price $" + p.toFixed(digits) + ".";
}

function esc(s) { return String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

function page({ name, symbol, price }) {
  const title = `Get ${symbol} on Uniswap`;
  const desc = `Buy, sell, and swap ${name} (${symbol}) on Uniswap. ${CHAIN_LABEL}.${fmtPrice(price)}`;
  const image = SITE + "/og.png";
  return `<!doctype html><html lang="en"><head>
<meta charset="utf-8">
<title>${esc(title)}</title>
<meta name="description" content="${esc(desc)}">
<link rel="canonical" href="${SITE}/">
<meta property="og:type" content="website">
<meta property="og:url" content="${SITE}/">
<meta property="og:site_name" content="Uniswap">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(desc)}">
<meta property="og:image" content="${image}">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:site" content="@Uniswap">
<meta name="twitter:title" content="${esc(title)}">
<meta name="twitter:description" content="${esc(desc)}">
<meta name="twitter:image" content="${image}">
<meta http-equiv="refresh" content="0;url=${DEST}">
</head><body style="font-family:sans-serif;background:#131313;color:#fff;display:grid;place-items:center;height:100vh;margin:0">
<p>Opening <a style="color:#FF37C7" href="${DEST}">${esc(title)}</a>&hellip;</p>
<script>location.replace(${JSON.stringify(DEST)})</script>
</body></html>`;
}

export default {
  async fetch(request) {
    const { pathname } = new URL(request.url);
    if (pathname === "/og.png") {
      const bytes = Uint8Array.from(atob(OG_PNG_B64), c => c.charCodeAt(0));
      return new Response(bytes, { headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" } });
    }
    if (pathname === "/robots.txt") return new Response("User-agent: *\nAllow: /\n", { headers: { "content-type": "text/plain" } });
    return new Response(page(await tokenInfo()), {
      headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300" },
    });
  },
};
